"""控制指令 API — CommandRegistry 管理 + 执行。"""
from fastapi import APIRouter
from pydantic import BaseModel

router = APIRouter(prefix='/commands', tags=['commands'])


class CommandExecuteRequest(BaseModel):
    command: str  # 如 "/status" 或 "status"
    args: str = ''


@router.get('')
async def list_commands():
    """列出已注册指令。"""
    from agent_runtime.server.app import get_agent_app
    app = get_agent_app()
    if not app:
        return []
    return app.commands.list_commands()


@router.post('/execute')
async def execute_command(req: CommandExecuteRequest):
    """执行指令。"""
    from agent_runtime.server.app import get_agent_app
    app = get_agent_app()
    if not app:
        return {'error': 'Agent 未初始化'}
    cmd_name = req.command if req.command.startswith('/') else f'/{req.command}'
    try:
        result = app.commands.execute(cmd_name, app=app, args_str=req.args)
        if isinstance(result, dict):
            return result
        return {'output': str(result)}
    except Exception as e:
        return {'success': False, 'error': str(e)}


@router.get('/{name}')
async def get_command(name: str):
    """指令详情。"""
    from agent_runtime.server.app import get_agent_app
    app = get_agent_app()
    if not app:
        return {'error': 'Agent 未初始化'}
    for cmd in app.commands.list_commands():
        if cmd.get('name') == name or cmd.get('name') == f'/{name}':
            return cmd
    return {'error': f'指令 {name} 不存在'}
